\begin{table}[b]
	\centering
	\label{T: Third-dimensional knives}
	\begin{tabular}{ c c c }
		k-navaja & Subespacio & Bases \\
		0-navaja & Escalar & $s$ \\
		1-navaja & Vector & $e_1, e_2, e_3$ \\
		2-navaja & Bivector & $\{e_1\wedge e_2, e_2 \wedge e_3, e_1 \wedge e_3 \}$ \\
		3-navaja & Trivector & $\{e_1 \wedge e_2 \wedge e_3\}$ \\
		Total & & $8$ navajas
	\end{tabular}
\end{table}
